      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Before `change_dates`, list the details and obtain explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the guest must be obtained before proceeding with the date change."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "The new total equals nightly_rate × number of nights. Quote it before confirmation.",
      "requirement": "The new total price must be calculated and quoted to the guest before confirmation (€180 × number of nights)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q15",
      "policy_quote": "Look up the guest with `get_guest` by guest ID and confirm the guest's last name before acting. Act only on reservations of that guest.",
      "requirement": "The guest's identity must be confirmed by matching the last name before acting on the reservation."
    }
  ]
